/**
 * H1 lane B — S06 residual risks (SEC02-N02 neighbourhood).
 *   (a) entropy: a tenant token registered through the API (POST/PUT /admin/tenants) is refused when it is long enough
 *       (>= 24) but trivially guessable: a repeated character, a short repeated pattern, a run of consecutive
 *       characters, fewer than 8 distinct characters or an estimate below 3 bits per character. Positive controls are
 *       generated by crypto.randomBytes.
 *   (b) distributed limiter: replicas share the authentication-failure count through the IDistributedRateLimiter
 *       contract (Redis in production); a source that spreads its guesses over replicas is throttled once the shared
 *       count reaches the limit. The local (memory) limiter stays the fallback when the shared counter fails.
 *   (c) source address: X-Forwarded-For spoofing with OTK_PROXY_TRUSTED_HOPS=0 and =1; IPv6 /64 grouping.
 * In-memory stores only; no network (the shared counter is an in-memory implementation of the shared interface).
 */
import { describe, it, before, after, beforeEach } from 'node:test';
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import { EventEmitter } from 'node:events';
import type { IncomingMessage, ServerResponse, Server } from 'node:http';
import type { AddressInfo } from 'node:net';

process.env['OTK_RECEIPT_LOG'] = '';
process.env['OTK_DB_URL'] = '';
process.env['OTK_TENANT_LOG'] = '';
process.env['PROVER_URL'] = 'disabled';
process.env['OPENAI_API_KEY'] = 'operator-provider-key-fixture';
delete process.env['OTK_REDIS_URL'];
delete process.env['OTK_TENANTS'];
delete process.env['OTK_PROXY_ALLOW_UNAUTHENTICATED'];

/* eslint-disable @typescript-eslint/no-explicit-any */
const RUN = Date.now().toString(36);
const PLATFORM = `lb-s06-platform-${RUN}-0123456789abcdef`;
const A = `lb-s06a-${RUN}`; const A_TOKEN = `lb-s06-a-operator-token-${RUN}-0123456789`;
const platform = { 'x-admin-key': PLATFORM };
const j = (o: unknown) => JSON.stringify(o);

let routes: any; let registry: any; let tenantCrud: any; let lim: any; let gw: any; let rlMod: any; let talRt: any; let plans: any;

function mockReq(method: string, url: string, body = '', headers: Record<string, string> = {}): IncomingMessage {
  const em = new EventEmitter(); let sent = false;
  em.on('newListener', (e: string) => { if (e === 'end' && !sent) { sent = true; setImmediate(() => { if (body) em.emit('data', Buffer.from(body)); em.emit('end'); }); } });
  return Object.assign(em, { method, url, headers: { 'content-type': 'application/json', ...headers }, socket: { remoteAddress: '127.0.0.1' }, destroy: () => {} }) as unknown as IncomingMessage;
}
class MockRes extends EventEmitter {
  statusCode = 200; body = ''; headersSent = false; hdrs: Record<string, unknown> = {};
  setHeader(k: string, v: unknown) { this.hdrs[k.toLowerCase()] = v; }
  getHeader(k: string) { return this.hdrs[k.toLowerCase()]; }
  removeHeader() { /* noop */ }
  writeHead(c: number, h?: unknown) { this.statusCode = c; if (h && typeof h === 'object') Object.assign(this.hdrs, h); this.headersSent = true; return this; }
  flushHeaders() { /* noop */ }
  write(d: unknown) { this.body += String(d); return true; }
  end(d?: unknown) { if (d !== undefined && d !== null) this.body += String(d); this.headersSent = true; this.emit('finish'); return this; }
}
async function call(method: string, url: string, headers: Record<string, string> = {}, body = ''): Promise<{ status: number; body: string }> {
  const res = new MockRes();
  await routes.handleRequest(mockReq(method, url, body, headers), res as unknown as ServerResponse);
  return { status: res.statusCode, body: res.body };
}

let server: Server; let base = ''; let upstreamCalls = 0;
const realFetch = globalThis.fetch;
async function proxyCall(token: string, xff?: string) {
  const headers: Record<string, string> = { 'content-type': 'application/json', authorization: `Bearer ${token}` };
  if (xff) headers['x-forwarded-for'] = xff;
  const r = await realFetch(`${base}/v1/chat/completions`, { method: 'POST', headers, body: j({ model: 'gpt-4o', messages: [] }) });
  await r.text();
  return { status: r.status, retryAfter: r.headers.get('retry-after') };
}
/** let the asynchronous shared-counter update of the last failure land */
async function flush() { for (let i = 0; i < 3; i++) await new Promise((r) => setImmediate(r)); }

const saved: Record<string, string | undefined> = {};
before(async () => {
  for (const k of ['OTK_ADMIN_KEY', 'OTK_PROXY_TRUSTED_HOPS', 'OTK_PROXY_AUTH_FAIL_MAX']) saved[k] = process.env[k];
  process.env['OTK_ADMIN_KEY'] = PLATFORM;
  delete process.env['OTK_PROXY_AUTH_FAIL_MAX']; delete process.env['OTK_PROXY_TRUSTED_HOPS'];
  routes = await import('../../src/api/routes.js');
  registry = await import('../../src/api/tenantKeyRegistry.js');
  tenantCrud = await import('../../src/api/tenantCrud.js');
  lim = await import('../../src/security/authFailureLimiter.js');
  gw = await import('../../src/proxy/ProxyGateway.js');
  rlMod = await import('../../src/security/IDistributedRateLimiter.js');
  talRt = await import('../../src/security/talRuntime.js');
  plans = await import('../../src/billing/PlanRegistry.js');
  registry.clearRegistry(); registry.clearHashRegistryForTest(); tenantCrud.clearTenantsForTest();
  registry.registerToken(A_TOKEN, A, 'OPERATOR');
  globalThis.fetch = (async (input: string | URL | Request, init?: RequestInit) => {
    const url = String(input instanceof Request ? input.url : input);
    if (url.startsWith('https://')) {
      upstreamCalls++;
      return new Response(j({ id: `chatcmpl-lbs06-${RUN}-${upstreamCalls}`, model: 'gpt-4o', usage: { prompt_tokens: 1, completion_tokens: 0 } }), { status: 200, headers: { 'content-type': 'application/json' } });
    }
    return realFetch(input as string, init);
  }) as typeof fetch;
  server = gw.startProxyGateway({ port: 0 });
  await new Promise<void>((r) => (server.listening ? r() : server.once('listening', () => r())));
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});
after(async () => {
  globalThis.fetch = realFetch;
  await new Promise<void>((r) => server.close(() => r()));
  registry.clearRegistry(); tenantCrud.clearTenantsForTest(); lim.resetProxyAuthFailureLimiterForTest();
  lim.setProxyAuthFailureSharedCounter?.(undefined);
  plans.resetPlanStoreForTest();
  for (const [k, v] of Object.entries(saved)) { if (v === undefined) delete process.env[k]; else process.env[k] = v; }
});
beforeEach(() => { lim.resetProxyAuthFailureLimiterForTest(); upstreamCalls = 0; talRt.resetAccountingLayerForTest(); plans.resetPlanStoreForTest(); });

describe('S06b (a) low-entropy tenant tokens are refused on the API registration paths', () => {
  const weak = [
    'a'.repeat(28),
    '0123456789012345678901234',
    'abcdefghijklmnopqrstuvwxyz',
    'ab'.repeat(14),
    'x'.repeat(24) + '1',
    'abc123abc123abc123abc123abc1',
  ];
  it('POST: each weak token >= 24 characters → 400 and is not registered', async () => {
    for (const [i, t] of weak.entries()) {
      assert.ok(t.length >= 24, t);
      const r = await call('POST', '/admin/tenants', platform, j({ tenantId: `lb-weak-${i}-${RUN}`, token: t }));
      assert.equal(r.status, 400, `${t}: ${r.body}`);
      assert.equal(registry.resolveTokenContext(t), null, t);
    }
  });

  it('PUT: a weak token → 400 and the tenant keeps its token', async () => {
    const tid = `lb-weak-put-${RUN}`; const tok = crypto.randomBytes(24).toString('base64url');
    assert.equal((await call('POST', '/admin/tenants', platform, j({ tenantId: tid, token: tok }))).status, 201);
    assert.equal((await call('PUT', `/admin/tenants/${tid}`, platform, j({ token: 'a'.repeat(30) }))).status, 400);
    assert.equal(registry.resolveTokenContext(tok)?.tenantId, tid);
  });

  it('positive controls: random tokens (base64url, hex) and a descriptive token with a random part → 201', async () => {
    const good = [
      crypto.randomBytes(24).toString('base64url'),
      crypto.randomBytes(16).toString('hex'),
      `tenant-acme-prod-${crypto.randomBytes(12).toString('hex')}`,
    ];
    for (const [i, t] of good.entries()) {
      const r = await call('POST', '/admin/tenants', platform, j({ tenantId: `lb-good-${i}-${RUN}`, token: t }));
      assert.equal(r.status, 201, `${t}: ${r.body}`);
    }
  });
});

describe('S06b (b) authentication-failure limiter shared across replicas', () => {
  it('two replicas sharing one counter: 10 + 10 failures of one source → both replicas throttle it', async () => {
    const shared = new rlMod.MemoryDistributedRateLimiter();
    const opts = { max: 20, windowMs: 60_000, maxEntries: 100 };
    const r1 = new lim.AuthFailureLimiter(opts, shared);
    const r2 = new lim.AuthFailureLimiter(opts, shared);
    for (let i = 0; i < 10; i++) await r1.recordFailure('ip4:203.0.113.77');
    for (let i = 0; i < 10; i++) await r2.recordFailure('ip4:203.0.113.77');
    await flush();
    assert.ok(r2.throttledFor('ip4:203.0.113.77') >= 1, 'the replica that crossed the shared limit throttles');
    await r1.recordFailure('ip4:203.0.113.77'); await flush();
    assert.ok(r1.throttledFor('ip4:203.0.113.77') >= 1, 'the other replica throttles on its next failure');
    assert.equal(r1.throttledFor('ip4:198.51.100.1'), 0, 'other sources unaffected');
  });

  it('shared counter failing → the local memory limiter still applies (fallback)', async () => {
    const broken = { check: async () => { throw new Error('redis down'); }, reset: async () => {}, clear: async () => {} };
    const l = new lim.AuthFailureLimiter({ max: 3, windowMs: 60_000, maxEntries: 100 }, broken);
    for (let i = 0; i < 3; i++) await l.recordFailure('ip4:192.0.2.5');
    await flush();
    assert.ok(l.throttledFor('ip4:192.0.2.5') >= 1);
  });

  it('proxy: failures recorded by other replicas in the shared counter + one local failure → the valid token is throttled', async () => {
    const shared = new rlMod.MemoryDistributedRateLimiter();
    lim.setProxyAuthFailureSharedCounter(shared); lim.resetProxyAuthFailureLimiterForTest();
    process.env['OTK_PROXY_TRUSTED_HOPS'] = '1';
    try {
      const src = '203.0.113.88';
      // 19 failures of this source seen by other replicas (direct writes to the shared backend)
      const cfg = lim.sharedAuthFailConfig({ max: 20, windowMs: 60_000 });
      for (let i = 0; i < 19; i++) await shared.check(lim.sharedAuthFailKey(`ip4:${src}`), cfg);
      assert.equal((await proxyCall(`lb-s06-guess-${RUN}`, src)).status, 401);
      await flush();
      const blocked = await proxyCall(A_TOKEN, src);
      assert.equal(blocked.status, 429, 'the 20th failure in the cluster throttles the source on this replica too');
      assert.ok(Number(blocked.retryAfter) >= 1);
      assert.equal((await proxyCall(A_TOKEN, '198.51.100.99')).status, 200, 'other sources unaffected (control)');
      assert.equal(upstreamCalls, 1);
    } finally { delete process.env['OTK_PROXY_TRUSTED_HOPS']; lim.setProxyAuthFailureSharedCounter(undefined); }
  });
});

describe('S06b (c) source address: X-Forwarded-For spoofing and IPv6 grouping', () => {
  const req = (addr: string, xff?: string) => ({ socket: { remoteAddress: addr }, headers: xff === undefined ? {} : { 'x-forwarded-for': xff } }) as any;

  it('OTK_PROXY_TRUSTED_HOPS=0 (default): X-Forwarded-For is ignored, whatever the client writes', () => {
    delete process.env['OTK_PROXY_TRUSTED_HOPS'];
    const k = lim.sourceKey(req('10.9.8.7'));
    for (const xff of ['1.2.3.4', '1.2.3.4, 5.6.7.8', '::1', 'garbage', '']) assert.equal(lim.sourceKey(req('10.9.8.7', xff)), k, xff);
    process.env['OTK_PROXY_TRUSTED_HOPS'] = '0';
    try { assert.equal(lim.sourceKey(req('10.9.8.7', '1.2.3.4')), k); } finally { delete process.env['OTK_PROXY_TRUSTED_HOPS']; }
  });

  it('OTK_PROXY_TRUSTED_HOPS=1: the right-most entry (added by the trusted proxy) is the source; entries prepended by the client do not change it', () => {
    process.env['OTK_PROXY_TRUSTED_HOPS'] = '1';
    try {
      const k = lim.sourceKey(req('10.0.0.1', '203.0.113.9'));
      assert.equal(k, 'ip4:203.0.113.9');
      for (const spoof of ['1.1.1.1', '1.1.1.1, 2.2.2.2', `198.51.100.${Math.floor(Math.random() * 250)}`]) {
        assert.equal(lim.sourceKey(req('10.0.0.1', `${spoof}, 203.0.113.9`)), k, spoof);
      }
      assert.equal(lim.sourceKey(req('10.0.0.1')), 'ip4:10.0.0.1', 'no header → socket address');
      assert.equal(lim.sourceKey(req('10.0.0.1', '2001:db8:aa:bb:1::1')), lim.sourceKey(req('10.0.0.1', '2001:db8:aa:bb:ffff::2')), 'IPv6 in XFF grouped by /64');
    } finally { delete process.env['OTK_PROXY_TRUSTED_HOPS']; }
  });

  it('proxy, hops=1: guesses with a rotating spoofed left-most XFF entry are throttled as one source', async () => {
    process.env['OTK_PROXY_TRUSTED_HOPS'] = '1'; lim.resetProxyAuthFailureLimiterForTest();
    try {
      for (let i = 0; i < 20; i++) await proxyCall(`lb-s06-xff-${i}-${RUN}`, `100.64.0.${i}, 203.0.113.44`);
      assert.equal((await proxyCall(A_TOKEN, `100.64.1.1, 203.0.113.44`)).status, 429);
    } finally { delete process.env['OTK_PROXY_TRUSTED_HOPS']; }
  });

  it('IPv6: one /64 is one source (compressed, expanded, upper case, IPv4-mapped handled); different /64 are distinct', () => {
    const k = lim.sourceKey(req('2001:db8:1:2::1'));
    assert.equal(k, 'ip6:2001:db8:1:2::/64');
    for (const a of ['2001:0db8:0001:0002:0000:0000:0000:0009', '2001:DB8:1:2:ffff:ffff:ffff:ffff', '2001:db8:1:2:a:b:c:d']) assert.equal(lim.sourceKey(req(a)), k, a);
    assert.notEqual(lim.sourceKey(req('2001:db8:1:3::1')), k);
    assert.equal(lim.sourceKey(req('::ffff:192.0.2.1')), 'ip4:192.0.2.1');
  });
});
